<script setup lang="ts">
import type {PracticeQuestionInput} from '@/api/practice'
import {questionProblems} from '@/practice/admin-draft'
defineProps<{questions:PracticeQuestionInput[];reviewed:string[];busy:boolean;wordBank?:string[];bulkDisabled?:boolean}>()
const emit=defineEmits<{jump:[key:string,field:string];review:[key:string,checked:boolean];reviewAll:[]}>()
</script>
<template><section class="practice-panel practice-overview" id="practice-overview"><h2>全部题目总览与校对</h2><div class="practice-actions"><button type="button" :disabled="busy||bulkDisabled||questions.every(q=>reviewed.includes(q.key))" @click="emit('reviewAll')">整组确认校对</button><span class="practice-hint">已校对 {{questions.filter(q=>reviewed.includes(q.key)).length}} / {{questions.length}} 题</span></div><p v-if="bulkDisabled" class="practice-hint">请先补齐题目问题，再确认整组校对。</p><p class="practice-hint">集中核对题干、正确选项和解析摘要。修改本题内容后需要重新校对。</p><article v-for="(q,n) in questions" :key="q.key" class="practice-overview-row"><div><h3>{{q.type==='CLOZE'?'第 '+q.stem+' 空':(q.type==='MATCH'?36+n:n+1)+'. '+(q.stem||'题干待填写')}}</h3><p><strong>正确选项：</strong>{{q.correctOption?q.correctOption+'. '+(q.type==='MATCH'?'段':q.type==='CLOZE'?wordBank?.['ABCDEFGHIJKLMNO'.indexOf(q.correctOption)]:q.options['ABCD'.indexOf(q.correctOption)]):'未设置答案'}}</p><p class="practice-hint">解析：{{q.explanation?q.explanation.slice(0,180)+(q.explanation.length>180?'…':''):'缺解析'}}</p><span class="practice-tag">{{questionProblems(q,reviewed.includes(q.key)).join(' · ')||'已校对'}}</span></div><div><button :disabled="busy" @click="emit('jump',q.key,'stem')">编辑第{{q.type==='MATCH'?36+n:n+1}}题</button><label class="practice-checkbox"><input type="checkbox" :checked="reviewed.includes(q.key)" :disabled="busy" @change="emit('review',q.key,($event.target as HTMLInputElement).checked)">已校对</label></div></article></section></template>
